-- femboy.gg UI | login + role ESP + tracer fallback patch
-- Library: original Lumen build (same loader as the working example).
-- License key: "femboy.gg"

local Femboy = loadstring(game:HttpGet("https://raw.githubusercontent.com/chromatiks/Lumen/main/Library.lua"))()

Femboy.SetConfigFolder("femboy")

-- ===== femboy.gg HUD: watermark / keybind list / scale / smooth menu =====
-- Self-contained: only uses Femboy's public table and every step is pcall-guarded,
-- so a failed patch can never stop the menu from loading.
local Hud = {
	Binds = {},
	Toggles = {},
	Links = {},
	Pop = 1,
	Settings = { Watermark = true, KeybindList = false, AutoScale = true, Animate = true, Scale = 1, KeybindScale = 1 },
}

do
	local Players = game:GetService("Players")
	local RunService = game:GetService("RunService")
	local UserInputService = game:GetService("UserInputService")
	local GuiService = game:GetService("GuiService")
	local CoreGui = game:GetService("CoreGui")

	local BASE_W, BASE_H = 658, 461
	local UIT = Enum.UserInputType
	local FADE_TIME = 0.22

	FEMBOY_CHARACTER_B64 = [==[

]==]

	local function DecodeBase64(Data)
		local Chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
		local Map = {}
		for i = 1, #Chars do
			Map[Chars:sub(i, i)] = i - 1
		end
		Data = Data:gsub("[^%w%+/]", "")
		local Out, n = {}, 0
		local Len = #Data
		local i = 1
		while i <= Len do
			local a = Map[Data:sub(i, i)]
			local b = Map[Data:sub(i + 1, i + 1)]
			local c = Map[Data:sub(i + 2, i + 2)]
			local d = Map[Data:sub(i + 3, i + 3)]
			if not a or not b then
				break
			end
			local Num = a * 262144 + b * 4096 + (c or 0) * 64 + (d or 0)
			n = n + 1
			Out[n] = string.char(math.floor(Num / 65536) % 256)
			if c then
				n = n + 1
				Out[n] = string.char(math.floor(Num / 256) % 256)
			end
			if d then
				n = n + 1
				Out[n] = string.char(Num % 256)
			end
			i = i + 4
		end
		return table.concat(Out)
	end

	local function Warn(Where, Err)
		warn("[femboy.gg] " .. Where .. ": " .. tostring(Err))
	end

	local function New(Class, Props, Parent)
		local Obj = Instance.new(Class)
		for Key, Value in pairs(Props) do
			pcall(function()
				Obj[Key] = Value
			end)
		end
		if Parent then
			Obj.Parent = Parent
		end
		return Obj
	end

	local function ThemeColor(Key, Default)
		local Value = Femboy.Theme and Femboy.Theme[Key]
		if typeof(Value) == "Color3" then
			return Value
		end
		return Default
	end

	-- Fixed graphite palette: no user-selectable color themes.
	local function KeybindPalette()
		return {
			bg = Color3.fromRGB(22, 22, 26),
			line = Color3.fromRGB(61, 61, 69),
			accent = Color3.fromRGB(236, 236, 241),
		}
	end

	local function IsPress(Input)
		return Input.UserInputType == UIT.MouseButton1 or Input.UserInputType == UIT.Touch
	end

	-- ---------- logo (embedded png -> custom asset) ----------
	local function LogoAsset()
		local GetAsset = getcustomasset or getsynasset
		if not (writefile and GetAsset) then
			return nil
		end
		local Ok, Asset = pcall(function()
			local Folder = "femboy"
			if makefolder and isfolder and not isfolder(Folder) then
				pcall(makefolder, Folder)
			end
			local Path = Folder .. "/logo_character.jpg"
			if not (isfile and isfile(Path)) then
				writefile(Path, DecodeBase64(FEMBOY_CHARACTER_B64))
			end
			return GetAsset(Path)
		end)
		if Ok and type(Asset) == "string" and Asset ~= "" then
			return Asset
		end
		return nil
	end

	-- ---------- state helpers ----------
	-- Best-effort boolean state of a Toggle: its own .State, else what we tracked from callbacks.
	local function ToggleState(Obj, Rec)
		if type(Obj) == "table" and type(Obj.State) == "boolean" then
			return Obj.State
		end
		if Rec then
			return Rec.Tracked == true
		end
		return false
	end

	local function Flip(Rec, State)
		-- callbacks that pass no argument still tell us "it changed"
		if type(State) == "boolean" then
			Rec.Tracked = State
		else
			Rec.Tracked = not Rec.Tracked
		end
		return Rec.Tracked
	end

	-- ---------- scale ----------
	local function Viewport()
		local Camera = workspace.CurrentCamera
		local Size = Camera and Camera.ViewportSize or Vector2.new(1280, 720)
		local Inset = 0
		pcall(function()
			Inset = GuiService:GetGuiInset().Y
		end)
		return Size, Inset
	end

	function Hud.GetScale()
		if Hud.Settings.AutoScale then
			local Size, Inset = Viewport()
			local Fit = math.min((Size.X - 16) / BASE_W, (Size.Y - Inset - 16) / BASE_H)
			return math.clamp(Fit, 0.35, 1)
		end
		return math.clamp(Hud.Settings.Scale, 0.35, 1.25)
	end

	local function FindWindow()
		for _, Win in ipairs(Femboy.Windows or {}) do
			if type(Win) == "table" and typeof(Win.Canvas) == "Instance" and Win.Canvas.Parent then
				return Win.Canvas
			end
		end
		local Root = Femboy._Instance
		if typeof(Root) == "Instance" then
			local View = Viewport()
			local Best, BestArea = nil, 0
			for _, Child in ipairs(Root:GetChildren()) do
				if Child:IsA("GuiObject") then
					local Size = Child.AbsoluteSize
					local Full = Size.X >= View.X * 0.95 and Size.Y >= View.Y * 0.95
					local Area = Size.X * Size.Y
					if not Full and Area > BestArea then
						Best, BestArea = Child, Area
					end
				end
			end
			return Best
		end
		return nil
	end

	-- cached: the slider fires many times per second, so never rescan the gui tree here
	function Hud.GetCanvas()
		local Canvas = Hud.Canvas
		if Canvas and Canvas.Parent then
			return Canvas
		end
		Hud.Canvas = FindWindow()
		return Hud.Canvas
	end

	function Hud.ApplyScale()
		local Scale = Hud.GetScale()
		Hud.BaseScale = Scale

		local Canvas = Hud.GetCanvas()
		if Canvas then
			local Obj = Hud.ScaleObj
			if not (Obj and Obj.Parent == Canvas) then
				Obj = Canvas:FindFirstChildOfClass("UIScale") or New("UIScale", { Name = "FemboyScale" }, Canvas)
				Hud.ScaleObj = Obj
			end
			Obj.Scale = Scale * Hud.Pop
			Hud.HookCanvas(Canvas)
		end

		local HudScale = math.clamp(Scale, 0.65, 1)
		for _, Name in ipairs({ "Watermark", "KeybindList" }) do
			local Frame = Hud.Gui and Hud.Gui:FindFirstChild(Name)
			local Sc = Frame and Frame:FindFirstChild("HudScale")
			if Sc then
				Sc.Scale = HudScale * 0.92
			end
		end
	end

	-- coalesce bursts (slider drags) into one apply
	function Hud.RequestScale()
		if Hud.ScalePending then
			return
		end
		Hud.ScalePending = true
		task.delay(0.08, function()
			Hud.ScalePending = false
			local Ok, Err = pcall(Hud.ApplyScale)
			if not Ok then
				Warn("scale", Err)
			end
		end)
	end

	-- ---------- smooth open / close ----------
	local Fade = { Alpha = 1, Target = 1, Open = true, List = nil, Conn = nil, Internal = false }

	local function CollectFade(Root)
		local List = {}
		local function Add(Obj, Prop)
			local Ok, Value = pcall(function()
				return Obj[Prop]
			end)
			if Ok and type(Value) == "number" then
				List[#List + 1] = { Obj, Prop, Value }
			end
		end
		local function Visit(Obj)
			if Obj:IsA("GuiObject") then
				Add(Obj, "BackgroundTransparency")
				if Obj:IsA("TextLabel") or Obj:IsA("TextButton") or Obj:IsA("TextBox") then
					Add(Obj, "TextTransparency")
					Add(Obj, "TextStrokeTransparency")
				end
				if Obj:IsA("ImageLabel") or Obj:IsA("ImageButton") then
					Add(Obj, "ImageTransparency")
				end
				if Obj:IsA("ScrollingFrame") then
					Add(Obj, "ScrollBarImageTransparency")
				end
			elseif Obj:IsA("UIStroke") then
				Add(Obj, "Transparency")
			end
		end
		Visit(Root)
		for _, Descendant in ipairs(Root:GetDescendants()) do
			Visit(Descendant)
		end
		return List
	end

	local function Paint(Eased)
		local List = Fade.List
		if not List then
			return
		end
		local Inverse = 1 - Eased
		pcall(function()
			for _, Item in ipairs(List) do
				Item[1][Item[2]] = Item[3] + (1 - Item[3]) * Inverse
			end
		end)
		Hud.Pop = 0.94 + 0.06 * Eased
		local Obj = Hud.ScaleObj
		if Obj and Hud.BaseScale then
			Obj.Scale = Hud.BaseScale * Hud.Pop
		end
	end

	local function Restore()
		local List = Fade.List
		if List then
			pcall(function()
				for _, Item in ipairs(List) do
					Item[1][Item[2]] = Item[3]
				end
			end)
		end
		Fade.List = nil
		Hud.Pop = 1
		local Obj = Hud.ScaleObj
		if Obj and Hud.BaseScale then
			Obj.Scale = Hud.BaseScale
		end
	end

	local function FinishFade()
		if Fade.Conn then
			Fade.Conn:Disconnect()
			Fade.Conn = nil
		end
		Restore()
		if Fade.Target == 0 then
			local Canvas = Hud.Canvas
			if Canvas then
				Fade.Internal = true
				Canvas.Visible = false
				Fade.Internal = false
			end
		end
	end

	local function StepFade(Dt)
		local Direction = Fade.Target > Fade.Alpha and 1 or -1
		Fade.Alpha = math.clamp(Fade.Alpha + Direction * Dt / FADE_TIME, 0, 1)
		if (Direction == 1 and Fade.Alpha >= Fade.Target) or (Direction == -1 and Fade.Alpha <= Fade.Target) then
			Fade.Alpha = Fade.Target
		end
		local Eased = Fade.Alpha * Fade.Alpha * (3 - 2 * Fade.Alpha)
		Paint(Eased)
		if Fade.Alpha == Fade.Target then
			FinishFade()
		end
	end

	local function RunFade(Target)
		local Canvas = Hud.Canvas
		if not Canvas then
			return
		end
		if not Fade.List then
			Fade.List = CollectFade(Canvas)
		end
		Fade.Target = Target
		if not Fade.Conn then
			Fade.Conn = RunService.Heartbeat:Connect(StepFade)
		end
	end

	function Hud.HookCanvas(Canvas)
		if Hud.Hooked == Canvas then
			return
		end
		Hud.Hooked = Canvas
		Fade.Open = Canvas.Visible
		Fade.Alpha = Canvas.Visible and 1 or 0
		Fade.Target = Fade.Alpha
		Canvas:GetPropertyChangedSignal("Visible"):Connect(function()
			if Fade.Internal or not Hud.Settings.Animate then
				return
			end
			if Canvas.Visible then
				-- opening: start fully transparent, then fade in
				Fade.Open = true
				Fade.Alpha = 0
				Fade.List = CollectFade(Canvas)
				Paint(0)
				RunFade(1)
			else
				-- the library hid it instantly: keep it up and fade out instead
				Fade.Open = false
				Fade.Internal = true
				Canvas.Visible = true
				Fade.Internal = false
				RunFade(0)
			end
		end)
	end

	function Hud.SetOpen(Open)
		local Canvas = Hud.GetCanvas()
		if not Canvas then
			return
		end
		if Open then
			if Canvas.Visible then
				if Fade.Target ~= 1 then
					Fade.Open = true
					RunFade(1)
				end
			else
				Canvas.Visible = true
			end
		elseif Canvas.Visible then
			Canvas.Visible = false
		end
	end

	function Hud.ToggleMenu()
		local Canvas = Hud.GetCanvas()
		local Want = true
		if Canvas then
			Hud.HookCanvas(Canvas)
			Want = not (Canvas.Visible and Fade.Target == 1)
		end
		if type(Femboy.ToggleMenu) == "function" then
			pcall(Femboy.ToggleMenu, Want)
		end
		Hud.SetOpen(Want)
		if not Want then
			pcall(function()
				if Femboy.OpenPopup and Femboy.OpenPopup.Close then
					Femboy.OpenPopup.Close()
				end
			end)
		end
	end

	-- ---------- gui root ----------
	local function Mount(Gui)
		local Parents = {}
		if gethui then
			table.insert(Parents, function()
				return gethui()
			end)
		end
		table.insert(Parents, function()
			return CoreGui
		end)
		table.insert(Parents, function()
			return Players.LocalPlayer:WaitForChild("PlayerGui", 5)
		end)
		for _, Get in ipairs(Parents) do
			local Ok, Parent = pcall(Get)
			if Ok and Parent then
				pcall(function()
					local Old = Parent:FindFirstChild("femboyHud")
					if Old then
						Old:Destroy()
					end
				end)
				local Set = pcall(function()
					Gui.Parent = Parent
				end)
				if Set and Gui.Parent then
					return true
				end
			end
		end
		return false
	end

	local function Draggable(Frame)
		local Dragging, StartInput, StartPos = false, nil, nil
		Frame.InputBegan:Connect(function(Input)
			if not IsPress(Input) then
				return
			end
			Dragging = true
			StartInput = Input.Position
			StartPos = Frame.Position
			Input.Changed:Connect(function()
				if Input.UserInputState == Enum.UserInputState.End then
					Dragging = false
				end
			end)
		end)
		UserInputService.InputChanged:Connect(function(Input)
			if Dragging and (Input.UserInputType == UIT.MouseMovement or Input.UserInputType == UIT.Touch) then
				local Delta = Input.Position - StartInput
				Frame.Position = UDim2.new(StartPos.X.Scale, StartPos.X.Offset + Delta.X, StartPos.Y.Scale, StartPos.Y.Offset + Delta.Y)
			end
		end)
	end

	-- ---------- watermark ----------
	local function BuildWatermark(Gui)
		local Surface = ThemeColor("Surface", Color3.fromRGB(14, 14, 16))
		local Border = ThemeColor("Border", Color3.fromRGB(38, 38, 46))
		local Accent = Palette.accent

		local Frame = New("Frame", {
			Name = "Watermark",
			AnchorPoint = Vector2.new(0.5, 0),
			Position = UDim2.new(0.5, 0, 0, 10),
			AutomaticSize = Enum.AutomaticSize.X,
			Size = UDim2.fromOffset(0, 50),
			BackgroundColor3 = Surface,
			BorderSizePixel = 0,
			Active = true,
			ZIndex = 50,
			Visible = Hud.Settings.Watermark,
		}, Gui)
		New("UICorner", { CornerRadius = UDim.new(0, 12) }, Frame)
		New("UIStroke", { Color = Border, Thickness = 1, ApplyStrokeMode = Enum.ApplyStrokeMode.Border }, Frame)
		New("UIPadding", { PaddingLeft = UDim.new(0, 7), PaddingRight = UDim.new(0, 12) }, Frame)
		New("UIListLayout", {
			FillDirection = Enum.FillDirection.Horizontal,
			Padding = UDim.new(0, 8),
			VerticalAlignment = Enum.VerticalAlignment.Center,
			SortOrder = Enum.SortOrder.LayoutOrder,
		}, Frame)
		New("UIScale", { Name = "HudScale", Scale = 0.86 }, Frame)

		local Asset = LogoAsset()
		local Logo = New("ImageLabel", {
			Name = "Logo",
			LayoutOrder = 0,
			Size = UDim2.fromOffset(44, 44),
			BackgroundColor3 = Accent,
			BackgroundTransparency = Asset and 1 or 0,
			BorderSizePixel = 0,
			Image = Asset or "",
			ScaleType = Enum.ScaleType.Fit,
			ResampleMode = Enum.ResamplerMode.Default,
			ZIndex = 51,
		}, Frame)
		New("UICorner", { CornerRadius = UDim.new(1, 0) }, Logo)
		if not Asset then
			New("TextLabel", {
				Name = "LogoFallback", Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1,
				Font = Enum.Font.GothamBlack, Text = "f", TextSize = 25,
				TextColor3 = Color3.fromRGB(255, 255, 255), ZIndex = 52,
			}, Logo)
		end

		local function Chip(Text, Order, Dim)
			return New("TextLabel", {
				LayoutOrder = Order,
				AutomaticSize = Enum.AutomaticSize.X,
				Size = UDim2.fromOffset(0, 50),
				BackgroundTransparency = 1,
				Font = Enum.Font.GothamMedium,
				Text = Text,
				TextSize = 12,
				TextColor3 = Dim and Color3.fromRGB(150, 154, 170) or Color3.fromRGB(235, 236, 240),
				ZIndex = 51,
			}, Frame)
		end

		Chip("femboy.gg", 1, false)
		Chip("-", 2, true)
		local Fps = Chip("0 fps", 3, true)
		Chip("-", 4, true)
		local Ping = Chip("0 ms", 5, true)
		Chip("-", 6, true)
		local Clock = Chip(os.date("%H:%M:%S"), 7, true)

		local Frames, Last = 0, os.clock()
		Hud.StatsConn = RunService.RenderStepped:Connect(function()
			Frames = Frames + 1
			local Now = os.clock()
			if Now - Last >= 1 then
				Fps.Text = string.format("%d fps", Frames)
				local Value = 0
				pcall(function()
					Value = math.floor(game:GetService("Stats").Network.ServerStatsItem["Data Ping"]:GetValue())
				end)
				Ping.Text = string.format("%d ms", Value)
				Clock.Text = os.date("%H:%M:%S")
				Frames = 0
				Last = Now
			end
		end)

		-- tap / click (without dragging) toggles the menu
		Frame.InputBegan:Connect(function(Input)
			if not IsPress(Input) then
				return
			end
			local Start = Input.Position
			local Conn
			Conn = Input.Changed:Connect(function()
				if Input.UserInputState == Enum.UserInputState.End then
					Conn:Disconnect()
					if (Input.Position - Start).Magnitude < 8 then
						Hud.ToggleMenu()
					end
				end
			end)
		end)

		Hud.Watermark = Frame
	end

	-- ---------- keybind list ----------
	local KeyNames = {
		MouseButton1 = "MB1", MouseButton2 = "MB2", MouseButton3 = "MB3",
		LeftShift = "LShift", RightShift = "RShift", LeftControl = "LCtrl", RightControl = "RCtrl",
		LeftAlt = "LAlt", RightAlt = "RAlt", Backspace = "Back", Return = "Enter",
	}

	local function KeyName(Key)
		if typeof(Key) == "EnumItem" then
			return Key.Name
		end
		if type(Key) == "string" then
			return Key
		end
		return nil
	end

	local function ValidKey(Key)
		local Name = KeyName(Key)
		return Name ~= nil and Name ~= "" and Name ~= "Unknown" and Name ~= "None"
	end

	local function KeyText(Key)
		local Name = KeyName(Key)
		if not Name then
			return "-"
		end
		return KeyNames[Name] or Name
	end

	-- the key currently bound, tolerant of libraries that expose it differently
	local function BoundKey(Entry)
		local Obj = Entry.Obj
		if type(Obj) == "table" then
			local Key = Obj.Key
			if ValidKey(Key) then
				Entry.KeySeen = true
				return Key
			end
			if Entry.KeySeen then
				return nil -- it was bound before and has been cleared
			end
		end
		return Entry.Key0
	end

	local function BoundMode(Entry)
		local Obj = Entry.Obj
		if type(Obj) == "table" and type(Obj.Type) == "string" then
			return Obj.Type
		end
		return Entry.Mode
	end

	local function FeatureOn(Entry)
		local Tog = Hud.Toggles[Entry.Label]
		if not Tog then
			return nil -- no toggle on this row
		end
		return ToggleState(Tog.Obj, Tog)
	end

	local function Engaged(Entry)
		if BoundMode(Entry) == "Always" then
			return true
		end
		if Entry.CbSeen then
			return Entry.Tracked == true
		end
		return Entry.Own == true
	end

	local function KeyMatches(Key, Input)
		if typeof(Key) == "EnumItem" then
			return Input.KeyCode == Key or Input.UserInputType == Key
		end
		if type(Key) == "string" then
			return Input.KeyCode.Name == Key or Input.UserInputType.Name == Key
		end
		return false
	end

	local function OnInput(Input, Began)
		if UserInputService:GetFocusedTextBox() then
			return
		end
		for _, Entry in ipairs(Hud.Binds) do
			local Key = BoundKey(Entry)
			if Key and KeyMatches(Key, Input) then
				local Mode = BoundMode(Entry)
				if Mode == "Hold" then
					Entry.Own = Began
				elseif Mode == "Toggle" and Began then
					Entry.Own = not Entry.Own
				end
			end
		end
	end

	local function BuildList(Gui)
		local Palette = KeybindPalette()
		local Surface = Palette.bg
		local Border = Palette.line

		local Panel = New("Frame", {
			Name = "KeybindList",
			Position = UDim2.new(0, 14, 0.35, 0),
			Size = UDim2.fromOffset(240, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			BackgroundColor3 = Surface,
			BorderSizePixel = 0,
			Active = true,
			Visible = false,
			ZIndex = 50,
		}, Gui)
		New("UICorner", { CornerRadius = UDim.new(0, 10) }, Panel)
		New("UIStroke", { Color = Border, Thickness = 1, Transparency = 0.35, ApplyStrokeMode = Enum.ApplyStrokeMode.Border }, Panel)
		New("UIPadding", { PaddingTop = UDim.new(0, 9), PaddingBottom = UDim.new(0, 9), PaddingLeft = UDim.new(0, 12), PaddingRight = UDim.new(0, 12) }, Panel)
		New("UIListLayout", { Padding = UDim.new(0, 4), SortOrder = Enum.SortOrder.LayoutOrder }, Panel)
		New("UIScale", { Name = "HudScale" }, Panel)

		New("TextLabel", {
			Name = "Header",
			LayoutOrder = 0,
			Size = UDim2.new(1, 0, 0, 20),
			BackgroundTransparency = 1,
			Font = Enum.Font.GothamMedium,
			Text = "hotkeys",
			TextSize = 13,
			TextColor3 = KeybindPalette().accent,
			TextXAlignment = Enum.TextXAlignment.Left,
			ZIndex = 51,
		}, Panel)

		Draggable(Panel)
		Hud.List = Panel
		Hud.Rows = {}
	end

	local function PollLinks()
		for Key, Link in pairs(Hud.Links) do
			local Obj = Link.Obj
			if Link.Kind == "toggle" then
				if type(Obj) == "table" and type(Obj.State) == "boolean" and Obj.State ~= Link.Last then
					Link.Last = Obj.State
					Link.Apply(Obj.State)
				end
			elseif Link.Kind == "slider" then
				if type(Obj) == "table" and type(Obj.Value) == "number" and Obj.Value ~= Link.Last then
					Link.Last = Obj.Value
					Link.Apply(Obj.Value)
				end
			end
		end
	end

	function Hud.Refresh()
		pcall(PollLinks)

		local Panel = Hud.List
		if not Panel then
			return
		end

		local Shown = {}
		local Count = 0
		local Palette = KeybindPalette()
		local ScaleObject = Panel:FindFirstChildOfClass("UIScale")
		if ScaleObject then ScaleObject.Scale = math.clamp(Hud.Settings.KeybindScale or 1, 0.8, 2) end
		for Index, Entry in ipairs(Hud.Binds) do
			local Key = BoundKey(Entry)
			local On = FeatureOn(Entry)
			local Live = Engaged(Entry)
			local Visible = Key ~= nil
			if Visible then
				Count = Count + 1
				local Mode = BoundMode(Entry) or "Toggle"
				local Id = tostring(Index)
				Shown[Id] = true

				local Row = Hud.Rows[Id]
				if not Row then
					local Frame = New("Frame", {
						LayoutOrder = Index,
						Size = UDim2.new(1, 0, 0, 27),
						BackgroundColor3 = Color3.fromRGB(29, 29, 34),
						BackgroundTransparency = 0,
						ZIndex = 51,
					}, Panel)
					New("UICorner", { CornerRadius = UDim.new(0, 7) }, Frame)
					New("UIStroke", { Color = Color3.fromRGB(255, 255, 255), Thickness = 1, Transparency = 0.94 }, Frame)
					local function Cell(Name, Pos, Size, Align)
						return New("TextLabel", {
							Name = Name,
							Position = Pos,
							Size = Size,
							BackgroundTransparency = 1,
							Font = Enum.Font.GothamMedium,
							TextSize = 12,
							TextXAlignment = Align,
							TextTruncate = Enum.TextTruncate.AtEnd,
							ZIndex = 52,
						}, Frame)
					end
					Row = {
						Frame = Frame,
						Name = Cell("Name", UDim2.fromOffset(0, 0), UDim2.new(0.5, 0, 1, 0), Enum.TextXAlignment.Left),
						Key = Cell("Key", UDim2.fromScale(0.5, 0), UDim2.new(0.25, 0, 1, 0), Enum.TextXAlignment.Center),
						Mode = Cell("Mode", UDim2.fromScale(0.75, 0), UDim2.new(0.25, 0, 1, 0), Enum.TextXAlignment.Right),
					}
					Hud.Rows[Id] = Row
				end
				local Accent = ThemeColor("Accent", Color3.fromRGB(120, 140, 255))
				Row.Name.Text = Entry.Name
				Row.Key.Text = KeyText(Key)
				Row.Mode.Text = tostring(Mode)
				Row.Name.TextColor3 = Live and Color3.fromRGB(240, 241, 245) or Color3.fromRGB(150, 154, 170)
				Row.Key.TextColor3 = Live and Accent or Color3.fromRGB(110, 114, 130)
				Row.Mode.TextColor3 = Color3.fromRGB(150, 154, 170)
			end
		end

		for Id, Row in pairs(Hud.Rows) do
			if not Shown[Id] then
				Row.Frame:Destroy()
				Hud.Rows[Id] = nil
			end
		end

		Panel.Visible = Hud.Settings.KeybindList == true and Count > 0
	end

	-- ---------- remove the library's own watermark / keybind list ----------
	local function LooksLikeStats(Root)
		for _, Obj in ipairs(Root:GetDescendants()) do
			if Obj:IsA("TextLabel") then
				local Text = string.lower(Obj.Text)
				if Text:find("fps", 1, true) or Text:find("%d+%s*ms") then
					return true
				end
			end
		end
		return false
	end

	local function KillByTable()
		local Killed = 0
		for _, Name in ipairs({ "Watermark", "KeybindList" }) do
			local Tab = Femboy[Name]
			if type(Tab) == "table" then
				for _, Field in ipairs({ "Frame", "Container", "Holder", "Root" }) do
					local Obj = Tab[Field]
					if typeof(Obj) == "Instance" and not (Hud.Gui and Obj:IsDescendantOf(Hud.Gui)) then
						pcall(function()
							Obj.Visible = false
							Obj:Destroy()
						end)
						Killed = Killed + 1
					end
				end
			end
		end
		return Killed
	end

	-- time-sliced so it never causes a frame hitch
	local function KillByScan()
		local Killed = 0
		local Canvas = Hud.GetCanvas()
		local Roots = {}
		if gethui then
			pcall(function()
				table.insert(Roots, gethui())
			end)
		end
		table.insert(Roots, CoreGui)
		pcall(function()
			table.insert(Roots, Players.LocalPlayer:FindFirstChild("PlayerGui"))
		end)

		local Budget = 0
		for _, Root in ipairs(Roots) do
			for _, Gui in ipairs(Root:GetChildren()) do
				if Gui:IsA("ScreenGui") and Gui ~= Hud.Gui then
					local Found = {}
					for _, Obj in ipairs(Gui:GetDescendants()) do
						Budget = Budget + 1
						if Budget % 400 == 0 then
							task.wait()
						end
						if Obj:IsA("TextLabel") and string.lower(Obj.Text):match("^%s*femboy") then
							table.insert(Found, Obj)
						end
					end
					for _, Label in ipairs(Found) do
						local Target, Cur = Label, Label.Parent
						while Cur and Cur ~= Gui and Cur:IsA("GuiObject") and Cur.AbsoluteSize.Y <= 80 and Cur.AbsoluteSize.X <= 700 do
							Target, Cur = Cur, Cur.Parent
						end
						local IsWindow = Canvas and (Target == Canvas or Target:IsDescendantOf(Canvas) or Canvas:IsDescendantOf(Target))
						if Target ~= Label and Target.Parent and not IsWindow and LooksLikeStats(Target) then
							pcall(function()
								Target.Visible = false
								Target:Destroy()
							end)
							Killed = Killed + 1
						end
					end
				end
			end
		end
		return Killed
	end

	function Hud.KillLibraryHud(Wide)
		local Killed = 0
		local Ok, Result = pcall(KillByTable)
		if Ok then
			Killed = Killed + Result
		end
		if Wide then
			task.spawn(function()
				local Ok2, Result2 = pcall(KillByScan)
				if not Ok2 then
					Warn("watermark scan", Result2)
				end
			end)
		end
		return Killed
	end

	-- the library must not draw its own watermark / keybind list any more
	for _, Name in ipairs({ "SetWatermark", "SetKeybindList" }) do
		if type(Femboy[Name]) == "function" then
			Hud["Orig" .. Name] = Femboy[Name]
			Femboy[Name] = function() end
		end
	end

	-- ---------- public api ----------
	function Hud.Bind(Label, Props)
		-- A feature without an explicit Key in its script configuration is not a keybind.
		if not Props or not ValidKey(Props.Key) then
			return nil
		end
		local Entry = {
			Label = Label,
			Name = tostring(Label.Text or "Keybind"),
			Mode = Props.Type or "Toggle",
			Key0 = Props.Key,
			Tracked = false,
			Own = false,
		}
		local Original = Props.Callback
		Entry.Apply = Original
		Props.Callback = function(State, ...)
			Entry.CbSeen = true
			if type(State) == "boolean" then
				Entry.Tracked = State
			else
				Entry.Tracked = not Entry.Tracked
			end
			if Original then
				return Original(State, ...)
			end
		end
		local Obj = Label:Keybind(Props)
		Entry.Obj = Obj
		table.insert(Hud.Binds, Entry)
		return Obj
	end

	function Hud.Get(Name)
		for _, Entry in ipairs(Hud.Binds) do
			if Entry.Name == Name then
				return { Key = BoundKey(Entry), Type = BoundMode(Entry), Active = Engaged(Entry) }
			end
		end
		return nil
	end

	function Hud.Set(Name, Key, Mode)
		for _, Entry in ipairs(Hud.Binds) do
			if Entry.Name == Name then
				if Key == nil or ValidKey(Key) then
					Entry.Key0, Entry.KeySeen = Key, Key ~= nil
					if type(Entry.Obj) == "table" then pcall(function() Entry.Obj.Key = Key end) end
				end
				if Mode == "Toggle" or Mode == "Hold" or Mode == "Always" then
					Entry.Mode = Mode
					if type(Entry.Obj) == "table" then pcall(function() Entry.Obj.Type = Mode end) end
				end
				pcall(Hud.Refresh)
				return true
			end
		end
		return false
	end

	function Hud.Toggle(Name)
		for _, Entry in ipairs(Hud.Binds) do
			if Entry.Name == Name then
				Entry.Own = not Entry.Own
				Entry.CbSeen, Entry.Tracked = true, Entry.Own
				if Entry.Apply then pcall(Entry.Apply, Entry.Own) end
				pcall(Hud.Refresh)
				return Entry.Own
			end
		end
		return nil
	end

	function Hud.On(Name, State)
		for _, Entry in ipairs(Hud.Binds) do
			if Entry.Name == Name then
				Entry.Own = State == true
				Entry.CbSeen, Entry.Tracked = true, Entry.Own
				if Entry.Apply then pcall(Entry.Apply, Entry.Own) end
				pcall(Hud.Refresh)
				return true
			end
		end
		return false
	end

	function Hud.Destroy()
		if Hud.Gui then pcall(function() Hud.Gui:Destroy() end) end
		Hud.Gui, Hud.List, Hud.Watermark = nil, nil, nil
	end

	function Hud.Tog(Label, Props)
		local Rec = { Tracked = Props.State == true }
		local Original = Props.Callback
		Props.Callback = function(State, ...)
			Flip(Rec, State)
			if Original then
				return Original(State, ...)
			end
		end
		Rec.Obj = Label:Toggle(Props)
		Hud.Toggles[Label] = Rec
		return Rec.Obj
	end

	-- settings controls: callback + polling, so they work whatever the library passes to callbacks
	function Hud.SettingToggle(Section, Text, Key, Default, Apply)
		local Label = Section:Label({ Text = Text })
		local Rec = { Tracked = Default }
		local Link = { Kind = "toggle", Last = Default, Apply = Apply }
		Link.Obj = Label:Toggle({
			State = Default,
			Flag = "Hud" .. Key,
			Callback = function(State)
				local Value = Flip(Rec, State)
				if Value ~= Link.Last then
					Link.Last = Value
					Apply(Value)
				end
			end,
		})
		Hud.Links[Key] = Link
		return Link.Obj
	end

	function Hud.SettingSlider(Section, Props, Key, Apply)
		local Link = { Kind = "slider", Last = Props.Value, Apply = Apply }
		Props.Flag = "Hud" .. Key
		Props.Callback = function(Value)
			if type(Value) == "number" and Value ~= Link.Last then
				Link.Last = Value
				Apply(Value)
			end
		end
		Link.Obj = Section:Slider(Props)
		Hud.Links[Key] = Link
		return Link.Obj
	end

	function Hud.SetWatermark(State)
		Hud.Settings.Watermark = State == true
		if Hud.Watermark then
			Hud.Watermark.Visible = Hud.Settings.Watermark
		end
	end

	function Hud.SetKeybindList(State)
		Hud.Settings.KeybindList = State == true
		pcall(Hud.Refresh)
	end


	function Hud.SetKeybindScale(Percent)
		Hud.Settings.KeybindScale = math.clamp((tonumber(Percent) or 100) / 100, 0.8, 2)
		pcall(Hud.Refresh)
	end

	function Hud.SetAutoScale(State)
		Hud.Settings.AutoScale = State == true
		Hud.RequestScale()
	end

	function Hud.SetAnimate(State)
		Hud.Settings.Animate = State == true
	end

	function Hud.SetScale(Percent)
		if type(Percent) == "number" then
			Hud.Settings.Scale = Percent / 100
			Hud.RequestScale()
		end
	end

	function Hud.Start()
		local Gui = New("ScreenGui", {
			Name = "femboyHud",
			ResetOnSpawn = false,
			IgnoreGuiInset = true,
			DisplayOrder = 100,
			ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
		})
		if not Mount(Gui) then
			Warn("hud", "could not parent the HUD gui")
			return
		end
		Hud.Gui = Gui

		local Ok, Err = pcall(BuildWatermark, Gui)
		if not Ok then
			Warn("watermark", Err)
		end
		Ok, Err = pcall(BuildList, Gui)
		if not Ok then
			Warn("keybind list", Err)
		end
		Ok, Err = pcall(Hud.ApplyScale)
		if not Ok then
			Warn("scale", Err)
		end
		task.delay(0.15, function()
			pcall(Hud.ApplyScale)
		end)

		local Camera = workspace.CurrentCamera
		if Camera then
			Camera:GetPropertyChangedSignal("ViewportSize"):Connect(function()
				Hud.RequestScale()
			end)
		end

		-- own key tracking: the list does not depend on how the library reports key state
		UserInputService.InputBegan:Connect(function(Input)
			pcall(OnInput, Input, true)
		end)
		UserInputService.InputEnded:Connect(function(Input)
			pcall(OnInput, Input, false)
		end)

		task.spawn(function()
			local Tick = 0
			while Gui.Parent do
				Tick = Tick + 1
				local Done, Problem = pcall(Hud.Refresh)
				if not Done then
					Warn("keybind list refresh", Problem)
				end
				if Tick == 1 or Tick == 12 then
					Hud.KillLibraryHud(true)
				elseif Tick % 5 == 0 then
					Hud.KillLibraryHud(false)
				end
				task.wait(0.2)
			end
			if Hud.StatsConn then
				Hud.StatsConn:Disconnect()
			end
		end)
	end
end
-- ===== end HUD =====

