        local assetOk, characterAsset = pcall(function()
            local getAsset = getcustomasset or getsynasset
            if not (getAsset and writefile) then return nil end
            local folder = "femboy"
            if makefolder and isfolder and not isfolder(folder) then pcall(makefolder, folder) end
            local path = folder .. "/logo_character.jpg"
            if not (isfile and isfile(path)) then
                local data = FEMBOY_CHARACTER_B64:gsub("[^%w%+/=]", "")
                local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
                local bytes = {}
                local buffer, bits = 0, 0
                for i = 1, #data do
                    local c = data:sub(i, i)
                    if c ~= "=" then
                        local value = alphabet:find(c, 1, true)
                        if value then
                            buffer = (buffer * 64 + value - 1) % 16777216
                            bits = bits + 6
                            if bits >= 8 then
                                bits = bits - 8
                                bytes[#bytes + 1] = string.char(math.floor(buffer / (2 ^ bits)) % 256)
                            end
                        end
                    end
                end
                writefile(path, table.concat(bytes))
            end
            return getAsset(path)
        end)
