        button.TextColor3 = Color3.fromRGB(255, 255, 255)
        button.Parent = form
        Instance.new("UICorner", button).CornerRadius = UDim.new(0, 9)
        local buttonGradient = Instance.new("UIGradient", button)
        buttonGradient.Color = ColorSequence.new(Color3.fromRGB(157, 76, 244), Color3.fromRGB(92, 43, 190))
        buttonGradient.Rotation = 0

        local footer = Instance.new("TextLabel")
        footer.BackgroundTransparency = 1
        footer.Position = UDim2.new(0, 0, 1, -36)
        footer.Size = UDim2.new(1, 0, 0, 20)
        footer.Font = Enum.Font.Gotham
        footer.Text = "●  Secure local session"
        footer.TextSize = 10
        footer.TextColor3 = Color3.fromRGB(142, 132, 165)
        footer.TextXAlignment = Enum.TextXAlignment.Left
        footer.Parent = form

        local completed = false
        local function submit()
            if completed then return end
            if username.Text == "femboy" and password.Text == "femboy123" then
                completed = true
                if remember then
                    pcall(function()
                        if type(writefile) == "function" then writefile(rememberPath, rememberToken) end
                    end)
                else
                    pcall(function()
                        if type(isfile) == "function" and type(delfile) == "function" and isfile(rememberPath) then delfile(rememberPath) end
                    end)
                end
                button.Text = "Welcome"
                status.TextColor3 = Color3.fromRGB(125, 230, 165)
                status.Text = "Login successful"
                task.wait(0.25)
                loginGui:Destroy()
            else
                status.Text = "Incorrect username or password"
                password.Text = ""
            end
        end
        button.Activated:Connect(submit)
        password.FocusLost:Connect(function(enterPressed) if enterPressed then submit() end end)
        while loginGui.Parent and not completed do task.wait() end
    end
end

